def execute_command(image) -> List[ImagePatch]:
    image_patch = ImagePatch(image)
    car_patches = image_patch.find("white car")

    if not car_patches:
        return image_patch

    # Sort cars based on their horizontal center
    car_patches.sort(key=lambda p: p.horizontal_center)

    # Find the car that starts on the left and ends on the right
    for i in range(len(car_patches) - 1):
        if car_patches[i].horizontal_center < car_patches[i + 1].horizontal_center:
            return [car_patches[i], car_patches[i + 1]]

    return car_patches

